     1	package com.loja.pedidos.controller;
     2	
     3	import com.loja.pedidos.dto.CheckoutRequestDTO;
     4	import com.loja.pedidos.dto.ResumoDTO;
     5	import com.loja.pedidos.dto.ItemDTO;
     6	import com.loja.pedidos.repository.ProdutoRepository;
     7	import com.loja.pedidos.service.ResumoPedidoService;
     8	import com.loja.pedidos.service.ValidacaoService;
     9	import org.springframework.beans.factory.annotation.Autowired;
    10	import org.springframework.http.ResponseEntity;
    11	import org.springframework.web.bind.annotation.*;
    12	
    13	import java.math.BigDecimal;
    14	import java.util.List;
    15	
    16	@RestController
    17	@RequestMapping("/checkout")
    18	public class CheckoutController {
    19	    @Autowired
    20	    private ResumoPedidoService resumoPedidoService;
    21	
    22	    @Autowired
    23	    private ValidacaoService validacaoService;
    24	
    25	    @Autowired
    26	    private ProdutoRepository produtoRepository;
    27	
    28	    @PostMapping("/resumo")
    29	    public ResponseEntity<ResumoDTO> calcularResumo(@RequestBody CheckoutRequestDTO req) {
    30	        validacaoService.validarCheckout(req);
    31	        BigDecimal pesoTotal = calcularPesoTotal(req.getItens());
    32	        validacaoService.validarDisponibilidadeEntrega(req, pesoTotal);
    33	        validacaoService.validarCupomAplicavel(req.getCupom(), req);
    34	        ResumoDTO resumo = resumoPedidoService.calcularResumo(req);
    35	        validacaoService.validarFormaPagamentoDisponivel(req.getFormaPagamento(), resumo.getTotalFinal());
    36	        return ResponseEntity.ok(resumo);
    37	    }
    38	
    39	    private BigDecimal calcularPesoTotal(List<ItemDTO> itens) {
    40	        BigDecimal peso = BigDecimal.ZERO;
    41	        for (ItemDTO item : itens) {
    42	            var produto = produtoRepository.findById(item.getSku());
    43	            if (produto.isPresent()) {
    44	                BigDecimal pesoUnitario = produto.get().getPesoKg();
    45	                BigDecimal quantidade = new BigDecimal(item.getQuantidade());
    46	                peso = peso.add(pesoUnitario.multiply(quantidade));
    47	            }
    48	        }
    49	        return peso;
    50	    }
    51	}
