   247	    private BigDecimal calcularJuroCartao(BigDecimal total, int parcelas) {
   248	        BigDecimal taxaMensal = new BigDecimal("0.0199");
   249	        BigDecimal um = new BigDecimal("1");
   250	        BigDecimal umMaisTaxa = um.add(taxaMensal);
   251	
   252	        BigDecimal denom = um.subtract(
   253	            umMaisTaxa.pow(parcelas * -1, new java.math.MathContext(10, java.math.RoundingMode.HALF_EVEN))
