     6	public class MoneyUtil {
     7	    private static final BigDecimal HUNDRED = new BigDecimal("100");
     8	
     9	    public static BigDecimal roundToNearestEven(BigDecimal value) {
    10	        return value.setScale(2, RoundingMode.HALF_EVEN);
    11	    }
    12	
    13	    public static BigDecimal percentageOf(BigDecimal base, BigDecimal percentage) {
    14	        return roundToNearestEven(base.multiply(percentage).divide(HUNDRED, 10, RoundingMode.HALF_EVEN));
    15	    }
    16	
    17	    public static BigDecimal divideRounded(BigDecimal dividend, BigDecimal divisor) {
    18	        return roundToNearestEven(dividend.divide(divisor, 10, RoundingMode.HALF_EVEN));
    19	    }
    20	
    21	    public static BigDecimal add(BigDecimal... values) {
    22	        BigDecimal sum = BigDecimal.ZERO;
    23	        for (BigDecimal value : values) {
    24	            sum = sum.add(value);
    25	        }
    26	        return roundToNearestEven(sum);
    27	    }
    28	
    29	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
    30	        return roundToNearestEven(a.subtract(b));
    31	    }
    32	
    33	    public static BigDecimal max(BigDecimal a, BigDecimal b) {
    34	        return a.compareTo(b) >= 0 ? a : b;
    35	    }
    36	
    37	    public static BigDecimal min(BigDecimal a, BigDecimal b) {
    38	        return a.compareTo(b) <= 0 ? a : b;
