   198	    private BigDecimal calcularSeguro(BigDecimal subtotal, String regiao) {
   199	        BigDecimal percentual;
   200	        BigDecimal limite = null;
   201	
   202	        switch (regiao) {
   203	            case "SUDESTE":
   204	            case "SUL":
   205	                percentual = new BigDecimal("1");
   206	                break;
   207	            case "CENTRO_OESTE":
   208	                percentual = new BigDecimal("1.5");
   209	                break;
   210	            case "NORTE":
   211	                percentual = new BigDecimal("2.5");
   212	                limite = new BigDecimal("30.00");
   213	                break;
   214	            case "NORDESTE":
   215	                percentual = new BigDecimal("2");
   216	                limite = new BigDecimal("30.00");
   217	                break;
   218	            default:
   219	                percentual = new BigDecimal("1");
   220	        }
   221	
   222	        BigDecimal seguro = MoneyUtil.percentageOf(subtotal, percentual);
   223	        if (limite != null) {
   224	            seguro = MoneyUtil.min(seguro, limite);
   225	        }
   226	
   227	        return seguro;
   228	    }
