    31	    public FreteResult consultarFrete(String cep, BigDecimal pesoKg, String service) {
    32	        try {
    33	            long weightGrams = pesoKg.multiply(new BigDecimal("1000")).longValue();
    34	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    35	                translogUrl, cep, weightGrams, service);
    36	
    37	            JsonNode response = restTemplate.getForObject(url, JsonNode.class);
    38	
    39	            if (response.has("error")) {
    40	                if ("ZIP_NOT_SERVED".equals(response.get("error").asText())) {
    41	                    return new FreteResult(false, null, null);
    42	                }
    43	            }
    44	
    45	            long priceCents = response.get("price_cents").asLong();
    46	            long etaHours = response.get("eta_hours").asLong();
    47	
    48	            BigDecimal price = new BigDecimal(priceCents).divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
    49	            int dias = (int) Math.ceil((double) etaHours / 24);
    50	
    51	            return new FreteResult(true, price, dias);
    52	        } catch (RestClientException e) {
    53	            throw new PedidoException("TRANSPORTADORA_INDISPONIVEL",
    54	                "TransLog unavailable", HttpStatus.SERVICE_UNAVAILABLE);
    55	        } catch (Exception e) {
    56	            throw new PedidoException("TRANSPORTADORA_INDISPONIVEL",
